create or replace function public.reorder_page_sections(page text, ordered uuid[]) returns integer language plpgsql security definer set search_path = public as $$ declare moved integer; begin if not public.is_admin() then raise exception 'Only an admin can reorder page sections'; end if; if exists ( select 1 from unnest(ordered) as wanted(id) left join public.page_sections section on section.id = wanted.id where section.id is null or section.page_slug <> page ) then raise exception 'Every section must belong to the page being reordered'; end if; update public.page_sections set position = new_order.position - 1 from (select id, ordinality as position from unnest(ordered) with ordinality as t(id, ordinality)) as new_order where public.page_sections.id = new_order.id; get diagnostics moved = row_count; return moved; end; $$;
comment on function public.reorder_page_sections(text, uuid[]) is 'Renumber a page''s sections from the given order, in one statement so the deferrable unique constraint is checked once.';
revoke all on function public.reorder_page_sections(text, uuid[]) from public;
grant execute on function public.reorder_page_sections(text, uuid[]) to authenticated, service_role;
